<template>
<div class="container">
  <ol class="list-group list-group-numbered m-2">
  <li v-for="i in 5" class="list-group-item d-flex justify-content-between align-items-start">
    <div class="ms-2 me-auto"
    data-bs-toggle="modal" data-bs-target="#entry-approval"
    @click="openModal(1, 465)"
    >
      <div class="fw-bold">Subheading</div>
      Content for list item
    </div>
    <span class="badge text-bg-primary rounded-pill">14</span>
  </li>

</ol>
</div>

<h3>Entry approving block</h3>
<div class="container">
      <entryApprovalBlock
      :key="componentKey"
      :type="selectedType" 
      :entry_id="selectedId"
      @loaded="handleEntry"
      @submit="handleSubmit"
    />
</div>
  
<!-- modal starts -->
<div class="modal fade mymodal" id="entry-approval" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">Entry Approval Block</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close" ></button>
      </div>
<div class="modal-body" >

      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal">Close</button>

      </div>

    </div>
  </div>

</div>



</template>

<script setup>
    import { ref, inject } from 'vue';
    import entryApprovalBlock from '@/components/reusables/EntryApprovalBlock.vue';
    const showMessage = inject('showMessage')  
    const showError = inject('showError')
    import axios from 'axios';



const axiosInstance = axios.create({
    baseURL: process.env.VUE_APP_API_BASE_URL
});


const selectedType = ref(null)
const selectedId = ref(null)
const componentKey = ref(0)

const openModal = (type, id) => {
  selectedType.value = type
  selectedId.value = id
  componentKey.value++ 
}

const approvalRoles = ref([])

const handleEntry = (data) => {
  approvalRoles.value = data?.entry_type?.entry_approval_flows[0]?.entry_approval_steps[0]?.approval_group?.approval_roles
}

const handleSubmit = async (data) => {
  console.log('SUBMIT DATA:', data)
  const payload = {
    entry_id : data.entry_id,
    entry_type_id : 1,
    user_id :  data.user_id,
    action : data.status_name,
    comment : data.remark
  }
  try {
    const response = await axiosInstance.post('entry-approval-actions', payload)
    showMessage('Action Saved!')
  
    componentKey.value++
    
  } catch(error) {
    console.log(error)
    showError(error.message)
  }
}
</script>